def solve(n, edges, s, t):
    from collections import deque

    # Initialize distance array with infinity
    dist = [float('inf')] * n
    dist[s] = 0

    # Use BFS-like approach with a queue
    queue = deque()
    queue.append(s)

    # Dictionary to keep track of visited nodes
    visited = set()
    visited.add(s)

    # Dictionary to map nodes to their neighbors and weights
    neighbor_weights = {}
    for u, v, w in edges:
        if u not in neighbor_weights:
            neighbor_weights[u] = []
        neighbor_weights[u].append((v, w))

    # Process nodes in the queue
    while queue:
        current = queue.popleft()

        if current == t:
            return dist[t]

        if current not in neighbor_weights:
            continue

        for neighbor, weight in neighbor_weights[current]:
            if dist[neighbor] > dist[current] + weight:
                dist[neighbor] = dist[current] + weight
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append(neighbor)

    return -1
