def solve(n, edges, s, t):
    import heapq

    # Initialize distance to all nodes as infinity
    dist = [float('inf')] * n
    dist[s] = 0

    # Priority queue to process nodes by their current shortest distance
    pq = []
    heapq.heappush(pq, (dist[s], s))

    # Dictionary to keep track of visited nodes
    visited = {s}

    while pq:
        current_dist, current_node = heapq.heappop(pq)

        # If the current distance is greater than the known shortest path, skip
        if current_dist > dist[current_node]:
            continue

        # Iterate over the edges from the current node
        for u, v, w in edges:
            if u == current_node:
                if dist[v] > current_dist + w:
                    dist[v] = current_dist + w
                    if v not in visited:
                        heapq.heappush(pq, (dist[v], v))
                        visited.add(v)
            elif v == current_node:
                if dist[u] > current_dist + w:
                    dist[u] = current_dist + w
                    if u not in visited:
                        heapq.heappush(pq, (dist[u], u))
                        visited.add(u)

    return dist[t] if dist[t] != float('inf') else -1
