def solve(n, edges, s, t):
    from collections import deque

    # Initialize distance array with infinity
    dist = [float('inf')] * n
    dist[s] = 0

    # Use a deque for BFS-like processing
    queue = deque()
    queue.append(s)

    # Dictionary to keep track of visited nodes
    visited = [False] * n
    visited[s] = True

    # Dictionary to store the weights of edges
    weight_map = {}
    for u, v, w in edges:
        if u not in weight_map:
            weight_map[u] = {}
        weight_map[u][v] = w

    # Process nodes in the queue
    while queue:
        current = queue.popleft()
        if current == t:
            break
        if not visited[current]:
            continue
        for neighbor in weight_map.get(current, []):
            if not visited[neighbor]:
                dist[neighbor] = min(dist[neighbor], dist[current] + weight_map[current][neighbor])
                queue.append(neighbor)
                visited[neighbor] = True

    return dist[t] if dist[t] != float('inf') else -1
