def solve(n, edges, s, t):
    from collections import deque

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # Bellman-Ford algorithm to find shortest paths from s
    dist = [float('inf')] * n
    dist[s] = 0
    for i in range(n - 1):
        updated = False
        for u in range(n):
            if dist[u] != float('inf'):
                for v, w in adj[u]:
                    if dist[v] > dist[u] + w:
                        dist[v] = dist[u] + w
                        updated = True
        if not updated:
            break

    # Check if t is reachable
    if dist[t] == float('inf'):
        return -1
    else:
        return dist[t]
